  chromeGradient_c4: vec4f,
  chromeGradient_c5: vec4f,
  chromeGradient_c6: vec4f,
  chromeGradient_c7: vec4f,
  chromeGradient_pos0: vec4f,
  chromeGradient_pos1: vec4f,
  chromeGradient_count: f32,
  heightIntensity: f32,
  chromaSeparation: f32,
  noiseScale: f32,
  phase: f32,
  evolution: f32,
  noiseAngle: f32,
  stretch: f32,
  gradientOffset: f32,
  gradientRepeats: f32,
  roughness: f32,
